 * The owner's current primary identifier: the {@link #getMemberId() memberId}. It is
 * the single source of truth for "the identifier that identifies this owner", so
 * downstream consumers (such as the audit event) read it from here.
 */
@Transient
public String getPrimaryIdentifier() {
    return this.memberId;
}

/**
 * The {@link #getMemberId() memberId} with any collision-dedup suffix ({@code -<n>})
 * stripped, i.e. the {@code <REGION><FY><HASH8><CHK>} base whose segments have fixed
 * widths (CHK 1, HASH8 8, FY 2, REGION the remainder). Null when no memberId is set.
 */
private String memberIdBase() {
    if (this.memberId == null) {
        return null;
    }
    int dash = this.memberId.indexOf('-');
    return dash >= 0 ? this.memberId.substring(0, dash) : this.memberId;
}

